"use client";

import React, { useState, useMemo, useRef, useEffect } from "react";
import { 
  Calendar as CalendarIcon, 
  ChevronDown, 
  CheckCircle2, 
  UploadCloud, 
  Plane, 
  Stethoscope, 
  Briefcase, 
  Baby, 
  Umbrella, 
  Heart, 
  AlertOctagon, 
  Trash2,
  ArrowRight,
  User,
  AlertTriangle,
  RefreshCcw,
  Sparkles,
  Clock,
  RotateCcw,
  ChevronLeft,
  ChevronRight,
  Settings,
  Plus,
  Save,
  X
} from "lucide-react";

// ============================================================================
// 1. DEFAULT CONFIGURATION
// ============================================================================
const DEFAULT_CONFIG = {
  companyName: "IfBash", // Used internally/admin, not in header
  weekendDays: [0, 6], // 0=Sun, 6=Sat
  holidays: [
    { id: 1, date: "2026-01-26", name: "Republic Day" },
    { id: 2, date: "2026-02-14", name: "Valentine's" },
    { id: 3, date: "2026-03-25", name: "Holi" }
  ],
  leaveTypes: [
    { id: "annual", label: "Annual", balance: 18, accrual: 1.5, color: "text-blue-500", requiresDoc: false },
    { id: "sick", label: "Sick", balance: 12, accrual: 1.0, color: "text-rose-500", requiresDoc: true },
    { id: "casual", label: "Casual", balance: 6, accrual: 0.5, color: "text-amber-500", requiresDoc: false },
    { id: "comp", label: "Comp Off", balance: 3, accrual: 0, color: "text-emerald-500", requiresDoc: false },
    { id: "lop", label: "L.O.P", balance: 0, accrual: 0, color: "text-red-500", requiresDoc: false },
  ],
  approvers: [
    { id: 1, name: "Sarah J.", role: "Manager", avatar: "SJ" },
    { id: 2, name: "HR Dept", role: "Audit", avatar: "HR" }
  ],
  history: [
    { date: "2026-01-05", status: "approved", label: "Sick Leave" },
    { date: "2026-01-12", status: "rejected", label: "Casual" }, 
  ]
};

// ============================================================================
// 2. MAIN APP COMPONENT
// ============================================================================
export default function ConfigurablePortal() {
  const [config, setConfig] = useState(DEFAULT_CONFIG);
  const [view, setView] = useState<"user" | "admin">("user");

  return (
    <div className="h-screen w-full bg-slate-50 dark:bg-[#050505] font-sans text-slate-800 dark:text-slate-200 flex flex-col overflow-hidden transition-colors duration-300">
      
      {/* --- STRICT HEADER --- */}
      <div className="flex-none px-6 py-3 flex items-center justify-between bg-white dark:bg-[#111] border-b border-slate-200 dark:border-white/10 z-20 h-16">
         
         {/* LEFT: Title */}
         <div className="flex items-center gap-3">
            <div className="bg-indigo-600 p-2 rounded-xl text-white shadow-md shadow-indigo-500/20"><CalendarIcon className="h-5 w-5" /></div>
            <h1 className="text-lg font-bold text-slate-900 dark:text-white tracking-tight">Request Absence</h1>
         </div>

         {/* RIGHT: Approver Flow + Settings */}
         <div className="flex items-center gap-4">
            
            {/* The Approver Chain Visual */}
            <div className="hidden md:flex items-center gap-3 bg-slate-50 dark:bg-white/5 px-4 py-1.5 rounded-full border border-slate-100 dark:border-white/5">
                <span className="text-[10px] font-bold text-slate-400 uppercase tracking-wider mr-1">Approvers:</span>
                {config.approvers.map((p, i) => (
                <React.Fragment key={p.id}>
                    <div className="flex items-center gap-2" title={`${p.name} (${p.role})`}>
                        <div className="h-6 w-6 rounded-full bg-white dark:bg-[#222] border border-slate-200 dark:border-white/10 flex items-center justify-center text-[9px] font-bold text-slate-700 dark:text-slate-300 shadow-sm cursor-help">
                            {p.avatar}
                        </div>
                    </div>
                    {i < config.approvers.length - 1 && <ArrowRight className="h-3 w-3 text-slate-300" />}
                </React.Fragment>
                ))}
            </div>

            {/* Admin Toggle */}
            <button 
                onClick={() => setView(view === 'user' ? 'admin' : 'user')}
                className={`p-2 rounded-lg transition-all ${view === 'admin' ? 'bg-indigo-100 text-indigo-600' : 'hover:bg-slate-100 dark:hover:bg-white/10 text-slate-400'}`}
            >
                <Settings className="h-5 w-5" />
            </button>
         </div>
      </div>

      {/* CONTENT AREA */}
      <div className="flex-1 flex overflow-hidden relative">
          {view === "user" ? (
              <UserPortal config={config} />
          ) : (
              <AdminSettings config={config} setConfig={setConfig} close={() => setView("user")} />
          )}
      </div>
    </div>
  );
}

// ============================================================================
// 3. ADMIN SETTINGS (Configuration)
// ============================================================================
function AdminSettings({ config, setConfig, close }: { config: typeof DEFAULT_CONFIG, setConfig: any, close: () => void }) {
    const updateNested = (parent: string, index: number, field: string, value: any) => {
        const list = [...(config as any)[parent]];
        list[index] = { ...list[index], [field]: value };
        setConfig((prev: any) => ({ ...prev, [parent]: list }));
    };

    return (
        <div className="absolute inset-0 bg-slate-50 dark:bg-[#050505] p-6 overflow-y-auto custom-scrollbar flex flex-col items-center">
            <div className="w-full max-w-3xl space-y-6 pb-10">
                <div className="flex items-center justify-between">
                    <div>
                        <h2 className="text-2xl font-black text-slate-900 dark:text-white">Admin Configuration</h2>
                        <p className="text-sm text-slate-500">Modify system rules without code.</p>
                    </div>
                    <button onClick={close} className="flex items-center gap-2 bg-slate-900 dark:bg-indigo-600 text-white px-4 py-2 rounded-lg font-bold shadow-lg hover:scale-105 transition-transform"><Save className="h-4 w-4" /> Done</button>
                </div>

                {/* Approver Editor */}
                <div className="bg-white dark:bg-[#111] p-6 rounded-2xl border border-slate-200 dark:border-white/10 shadow-sm space-y-4">
                    <h3 className="text-sm font-bold uppercase tracking-widest text-indigo-500">Approval Workflow</h3>
                    <p className="text-xs text-slate-500">These people will appear in the header flow.</p>
                    <div className="space-y-2">
                        {config.approvers.map((a, i) => (
                            <div key={a.id} className="flex gap-2 items-center">
                                <span className="text-xs font-bold text-slate-300 w-6">#{i+1}</span>
                                <input type="text" value={a.name} onChange={(e) => updateNested('approvers', i, 'name', e.target.value)} className="flex-1 bg-slate-50 dark:bg-[#1a1a1a] border border-slate-200 dark:border-white/10 rounded-lg p-2 text-xs font-medium outline-none" placeholder="Name" />
                                <input type="text" value={a.avatar} onChange={(e) => updateNested('approvers', i, 'avatar', e.target.value)} className="w-16 bg-slate-50 dark:bg-[#1a1a1a] border border-slate-200 dark:border-white/10 rounded-lg p-2 text-xs font-medium outline-none text-center" placeholder="Initials" />
                            </div>
                        ))}
                    </div>
                </div>

                {/* Holiday Editor */}
                <div className="bg-white dark:bg-[#111] p-6 rounded-2xl border border-slate-200 dark:border-white/10 shadow-sm space-y-4">
                    <h3 className="text-sm font-bold uppercase tracking-widest text-indigo-500">Holidays</h3>
                    {config.holidays.map((h, i) => (
                        <div key={h.id} className="flex gap-2">
                            <input type="date" value={h.date} onChange={(e) => updateNested('holidays', i, 'date', e.target.value)} className="bg-slate-50 dark:bg-[#1a1a1a] border border-slate-200 dark:border-white/10 rounded-lg p-2 text-xs font-medium outline-none" />
                            <input type="text" value={h.name} onChange={(e) => updateNested('holidays', i, 'name', e.target.value)} className="flex-1 bg-slate-50 dark:bg-[#1a1a1a] border border-slate-200 dark:border-white/10 rounded-lg p-2 text-xs font-medium outline-none" />
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
}

// ============================================================================
// 4. USER PORTAL
// ============================================================================
function UserPortal({ config }: { config: typeof DEFAULT_CONFIG }) {
  const [currentDate, setCurrentDate] = useState(new Date(2026, 0, 1));
  const [mode, setMode] = useState<"single" | "range" | "multi">("range");
  const [range, setRange] = useState<{ start: string; end: string }>({ start: "", end: "" });
  const [multiDates, setMultiDates] = useState<string[]>([]);
  const [typeId, setTypeId] = useState(config.leaveTypes[0].id);
  const [reason, setReason] = useState("");
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);

  // Calendar Logic
  const calendarData = useMemo(() => {
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    let firstDayOfWeek = new Date(year, month, 1).getDay();
    firstDayOfWeek = firstDayOfWeek === 0 ? 6 : firstDayOfWeek - 1; 
    return { year, month, daysInMonth, firstDayOfWeek };
  }, [currentDate]);

  const handleDateClick = (day: number) => {
    const y = calendarData.year;
    const m = calendarData.month + 1;
    const dStr = `${y}-${m < 10 ? '0' + m : m}-${day < 10 ? '0' + day : day}`;

    const existing = config.history.find(r => r.date === dStr);
    
    // Logic: Block Approved/Pending. Allow Rejected (to re-apply).
    if (existing && (existing.status === 'approved' || existing.status === 'pending')) return;

    if (mode === "multi") {
      setMultiDates(prev => prev.includes(dStr) ? prev.filter(d => d !== dStr) : [...prev, dStr].sort());
    } else if (mode === "single") {
      setRange({ start: dStr, end: dStr });
    } else {
      if (!range.start || (range.start && range.end)) setRange({ start: dStr, end: "" });
      else {
        const s = new Date(range.start);
        const e = new Date(dStr);
        if (e < s) setRange({ start: dStr, end: range.start });
        else setRange({ ...range, end: dStr });
      }
    }
  };

  const handleQuickSelect = (type: 'today' | 'tomorrow') => {
    const today = new Date();
    if (type === 'tomorrow') today.setDate(today.getDate() + 1);
    const dStr = today.toISOString().split('T')[0];
    setMode('single');
    setRange({ start: dStr, end: dStr });
    setMultiDates([]);
    setCurrentDate(today);
  };

  // Stats Logic
  const stats = useMemo(() => {
    let days = 0, deduction = 0;
    const checkDay = (dStr: string) => {
      const dObj = new Date(dStr);
      const isHoliday = config.holidays.some(h => h.date === dStr);
      const isWeekend = config.weekendDays.includes(dObj.getDay());
      if (!isHoliday && !isWeekend) return 1;
      return 0;
    };

    if (mode === "multi") {
      days = multiDates.length;
      deduction = multiDates.reduce((acc, date) => acc + checkDay(date), 0);
    } else {
      if (range.start && range.end) {
        let cur = new Date(range.start);
        let end = new Date(range.end);
        while (cur <= end) {
          deduction += checkDay(cur.toISOString().split('T')[0]);
          days++;
          cur.setDate(cur.getDate() + 1);
        }
      } else if (range.start) {
          days = 1;
          deduction = checkDay(range.start);
      }
    }
    return { days, deduction };
  }, [range, multiDates, mode, typeId, calendarData, config]);

  const selectedType = config.leaveTypes.find(t => t.id === typeId) || config.leaveTypes[0];
  const hasDates = mode === "multi" ? multiDates.length > 0 : !!(range.start && range.end);
  const isFormValid = hasDates && reason.length > 0;

  // Granular Button Text
  let btnText = "Submit Request";
  if (!hasDates) btnText = mode === 'range' && range.start ? "Select End Date" : "Select Dates";
  else if (reason.length === 0) btnText = "Enter Reason";

  return (
    <div className="flex-1 flex overflow-hidden">
        
        {/* LEFT: CALENDAR */}
        <div className="flex-1 flex flex-col min-w-0 p-4 gap-4 overflow-hidden">
           <div className="flex-1 bg-white dark:bg-[#111] rounded-2xl border border-slate-200 dark:border-white/10 shadow-sm flex flex-col overflow-hidden relative">
              <div className="flex-none flex items-center justify-between px-5 py-3 border-b border-slate-100 dark:border-white/10 h-16">
                 <div className="flex items-center gap-4">
                     <div className="flex items-center gap-1">
                         <button onClick={() => setCurrentDate(new Date(currentDate.setMonth(currentDate.getMonth() - 1)))} className="p-1.5 rounded-lg hover:bg-slate-100 dark:hover:bg-white/10"><ChevronLeft className="h-4 w-4" /></button>
                         <h2 className="text-base font-bold text-slate-900 dark:text-white w-32 text-center select-none">{currentDate.toLocaleString('default', { month: 'long', year: 'numeric' })}</h2>
                         <button onClick={() => setCurrentDate(new Date(currentDate.setMonth(currentDate.getMonth() + 1)))} className="p-1.5 rounded-lg hover:bg-slate-100 dark:hover:bg-white/10"><ChevronRight className="h-4 w-4" /></button>
                     </div>
                     <button onClick={() => setCurrentDate(new Date())} className="text-[10px] font-bold bg-slate-100 dark:bg-white/10 text-slate-500 px-3 py-1.5 rounded-lg hover:bg-slate-200">Today</button>
                 </div>
                 <div className="flex gap-2 items-center">
                    <div className="flex bg-slate-100 dark:bg-white/5 p-1 rounded-lg">
                        {['single', 'range', 'multi'].map((m) => (
                        <button key={m} onClick={() => { setMode(m as any); setRange({start:"", end:""}); setMultiDates([]); }} className={`px-3 py-1.5 rounded-md text-[10px] font-bold capitalize transition-all ${mode === m ? "bg-white dark:bg-[#222] shadow-sm text-indigo-600 dark:text-indigo-300" : "text-slate-500 hover:text-slate-700 dark:hover:text-slate-300"}`}>{m}</button>
                        ))}
                    </div>
                    {(range.start || multiDates.length > 0) && <button onClick={() => { setMultiDates([]); setRange({start:"", end:""}); }} className="flex items-center gap-1 text-[10px] font-bold text-rose-500 hover:bg-rose-50 px-3 py-2 rounded-lg transition-colors"><Trash2 className="h-4 w-4" /></button>}
                 </div>
              </div>

              <div className="flex-1 p-4 overflow-y-auto">
                 <div className="grid grid-cols-7 gap-1 h-full content-start auto-rows-fr">
                    {['M', 'T', 'W', 'T', 'F', 'S', 'S'].map(d => <div key={d} className="text-center text-[10px] font-bold text-slate-400 uppercase mb-1">{d}</div>)}
                    {Array.from({ length: calendarData.firstDayOfWeek }).map((_, i) => <div key={`e-${i}`} />)}
                    {Array.from({ length: calendarData.daysInMonth }).map((_, i) => {
                       const day = i + 1;
                       const dateStr = `${calendarData.year}-${calendarData.month + 1 < 10 ? '0' + (calendarData.month + 1) : calendarData.month + 1}-${day < 10 ? '0' + day : day}`;
                       const holiday = config.holidays.find(h => h.date === dateStr);
                       const existing = config.history.find(r => r.date === dateStr);
                       const dObj = new Date(dateStr);
                       const isWeekend = config.weekendDays.includes(dObj.getDay());

                       let isSelected = false, inRange = false;
                       if (mode === "multi") isSelected = multiDates.includes(dateStr);
                       else {
                           isSelected = range.start === dateStr || range.end === dateStr;
                           inRange = range.start && range.end && dateStr > range.start && dateStr < range.end;
                       }

                       let btnClass = "border border-slate-100 dark:border-white/5 bg-white dark:bg-[#151515] text-slate-600 dark:text-slate-400 hover:border-indigo-300";
                       let label = null;
                       let isDisabled = false;

                       if (existing) {
                           if (existing.status === 'approved') { btnClass = "bg-emerald-50 dark:bg-emerald-900/20 border-emerald-200 text-emerald-700 opacity-60"; label = <span className="flex items-center gap-1"><CheckCircle2 className="h-2 w-2"/> {existing.label}</span>; isDisabled = true; }
                           else if (existing.status === 'pending') { btnClass = "bg-amber-50 dark:bg-amber-900/20 border-amber-200 text-amber-700 opacity-80"; label = <span className="flex items-center gap-1"><Clock className="h-2 w-2"/> {existing.label}</span>; isDisabled = true; }
                           else if (existing.status === 'rejected') { btnClass = isSelected ? "bg-indigo-600 text-white" : "bg-rose-50 dark:bg-rose-900/10 border-rose-200 text-rose-700 cursor-pointer"; label = !isSelected ? <span className="flex items-center gap-1"><RotateCcw className="h-2 w-2"/> Retry</span> : null; }
                       } else if (isSelected) btnClass = "bg-indigo-600 text-white shadow-lg z-10 border-indigo-600";
                       else if (inRange) btnClass = "bg-indigo-50 dark:bg-indigo-900/20 text-indigo-600 border-indigo-100";
                       else if (holiday) { btnClass = "bg-rose-50 dark:bg-rose-900/10 border-rose-100 text-rose-600"; label = holiday.name; }
                       else if (isWeekend) btnClass = "bg-slate-50 dark:bg-white/5 text-slate-300 dark:text-slate-600 border-transparent";

                       return (
                          <button key={day} onClick={() => handleDateClick(day)} disabled={isDisabled} className={`relative min-h-[3.5rem] w-full rounded-lg text-left p-1.5 transition-all group duration-200 ${btnClass}`}>
                             <span className={`text-xs font-bold leading-none ${isSelected ? 'text-white' : ''}`}>{day}</span>
                             {label && <span className={`absolute bottom-1 left-1 right-1 text-[8px] font-bold px-1 rounded truncate ${isSelected ? 'bg-white/20 text-white' : 'bg-white/60 dark:bg-black/40'}`}>{label}</span>}
                             {isSelected && <span className="absolute top-1.5 right-1.5"><Sparkles className="h-2.5 w-2.5 text-indigo-200 animate-pulse" /></span>}
                          </button>
                       )
                    })}
                 </div>
              </div>
           </div>
        </div>

        {/* RIGHT: SIDEBAR */}
        <div className="w-[360px] flex flex-col p-4 pl-0 gap-4 min-w-0 z-20">
           <div className="flex-1 bg-white dark:bg-[#111] rounded-2xl border border-slate-200 dark:border-white/10 shadow-lg flex flex-col overflow-hidden min-h-0">
              <div className="flex-none p-4 border-b border-slate-100 dark:border-white/10 space-y-3">
                 <div className="relative">
                    <label className="text-[9px] font-bold uppercase text-slate-400 mb-1 block tracking-wider">Leave Type</label>
                    <button onClick={() => setIsDropdownOpen(!isDropdownOpen)} className="w-full flex items-center justify-between bg-white dark:bg-[#1a1a1a] border border-slate-200 dark:border-white/10 rounded-xl p-2.5 hover:border-indigo-400 transition-all shadow-sm">
                       <span className="text-sm font-bold text-slate-800 dark:text-white">{selectedType.label}</span>
                       <ChevronDown className={`h-3.5 w-3.5 text-slate-400 transition-transform ${isDropdownOpen ? 'rotate-180' : ''}`} />
                    </button>
                    {isDropdownOpen && (
                       <div className="absolute top-full left-0 right-0 mt-2 bg-white dark:bg-[#1a1a1a] border border-slate-200 dark:border-white/10 rounded-xl shadow-2xl z-50 max-h-[300px] overflow-y-auto p-1 custom-scrollbar">
                          {config.leaveTypes.map(t => (
                             <button key={t.id} onClick={() => { setTypeId(t.id); setIsDropdownOpen(false); }} className="w-full flex items-center justify-between p-2 hover:bg-slate-50 dark:hover:bg-white/5 rounded-lg group transition-colors">
                                <span className="text-xs font-bold text-slate-700 dark:text-slate-300">{t.label}</span>
                                <span className="text-[9px] font-bold text-slate-400 bg-slate-100 dark:bg-white/10 px-2 py-1 rounded-md">{t.balance}</span>
                             </button>
                          ))}
                       </div>
                    )}
                 </div>
                 <div className="flex justify-between bg-slate-50 dark:bg-white/5 p-3 rounded-xl items-center border border-slate-100 dark:border-white/5">
                    <div className="text-center w-1/2 border-r border-slate-200 dark:border-white/10 pr-2"><p className="text-[9px] font-bold text-slate-400 uppercase tracking-wider">Days</p><p className="text-lg font-black text-slate-900 dark:text-white mt-1">{stats.days}</p></div>
                    <div className="text-center w-1/2 pl-2"><p className="text-[9px] font-bold text-slate-400 uppercase tracking-wider">Deduction</p><p className="text-lg font-black text-rose-500 mt-1">-{stats.deduction}</p></div>
                 </div>
              </div>

              <div className="flex-1 p-4 space-y-4 overflow-y-auto custom-scrollbar">
                 <div>
                    <label className="text-[9px] font-bold uppercase text-slate-400 mb-2 block tracking-wider">Reason</label>
                    <textarea 
                        className="w-full h-20 rounded-xl bg-slate-50 dark:bg-white/5 p-3 text-xs font-medium text-slate-900 dark:text-white focus:ring-2 focus:ring-indigo-500 focus:bg-white dark:focus:bg-black outline-none resize-none placeholder:text-slate-400" 
                        placeholder="Context..." 
                        value={reason} 
                        onChange={(e) => setReason(e.target.value)} 
                    />
                 </div>
              </div>
              
              <div className="flex-none p-4 border-t border-slate-100 dark:border-white/10 bg-slate-50/50 dark:bg-white/5">
                 <button 
                    disabled={!isFormValid} 
                    className={`w-full py-3.5 rounded-xl font-bold text-sm shadow-lg transition-all flex items-center justify-center gap-2 group ${isFormValid ? "bg-slate-900 dark:bg-indigo-600 text-white hover:scale-[1.02]" : "bg-slate-200 dark:bg-white/10 text-slate-400 cursor-not-allowed"}`}
                 >
                    {btnText}
                 </button>
              </div>
           </div>
        </div>
    </div>
  );
}